def load_policy(fetch, snapshots, now, report):
    try:
        return fetch()
    except TimeoutError:
        snapshot = snapshots.latest_verified()
        if snapshot is None or not 0 <= now - snapshot.saved_at <= 300:
            raise
        report("source_timeout_recovered")
        return snapshot.rules

